package com.streamcraft.core.runtime;
import com.fasterxml.jackson.databind.*; import com.streamcraft.core.model.DataEntity; import com.streamcraft.shared.influxdb.InfluxDbSourceConfig; import com.streamcraft.shared.influxdb.InfluxDbSourceConfig.CursorType; import com.streamcraft.shared.influxdb.InfluxDbSourceConfig.ReadMode; import java.net.*; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.sql.Timestamp; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.apache.flink.api.connector.source.*; import org.apache.flink.core.io.InputStatus; import org.slf4j.*;
final class InfluxDbSourceReader implements SourceReader<DataEntity,InfluxDbSourceSplit>{
 private static final Logger LOG=LoggerFactory.getLogger(InfluxDbSourceReader.class); private final SourceReaderContext context; private final InfluxDbSourceConfig config; private final Object lock=new Object(); private final ArrayDeque<Record> records=new ArrayDeque<>(); private final ArrayDeque<InfluxDbSourceSplit> pendingSplits=new ArrayDeque<>(); private final HttpClient client; private final ObjectMapper mapper=new ObjectMapper(); private InfluxDbSourceSplit split; private boolean started,exhausted,noMore; private int polls; private long nextPoll;
 InfluxDbSourceReader(SourceReaderContext c,InfluxDbSourceConfig cfg){context=c;config=cfg;client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(cfg.connectTimeoutMillis())).build();}
 public void start(){started=true;context.sendSplitRequest();}
 public InputStatus pollNext(ReaderOutput<DataEntity> out)throws Exception{synchronized(lock){if(!started)return InputStatus.NOTHING_AVAILABLE;if(split==null&&!pendingSplits.isEmpty())split=pendingSplits.removeFirst();if(split==null)return noMore?InputStatus.END_OF_INPUT:InputStatus.NOTHING_AVAILABLE;if(!records.isEmpty()){emit(out);return records.isEmpty()?InputStatus.NOTHING_AVAILABLE:InputStatus.MORE_AVAILABLE;}if(exhausted)return InputStatus.END_OF_INPUT;if(System.currentTimeMillis()<nextPoll)return InputStatus.NOTHING_AVAILABLE;load();if(!records.isEmpty()){emit(out);return records.isEmpty()?InputStatus.NOTHING_AVAILABLE:InputStatus.MORE_AVAILABLE;}if(config.readMode()==ReadMode.FULL){split=null; if(!pendingSplits.isEmpty()) return pollNext(out); exhausted=true;return noMore?InputStatus.END_OF_INPUT:InputStatus.NOTHING_AVAILABLE;}if(config.maxPolls()>0&&polls>=config.maxPolls()){exhausted=true;return InputStatus.END_OF_INPUT;}nextPoll=System.currentTimeMillis()+config.pollIntervalMillis();return InputStatus.NOTHING_AVAILABLE;}}
 public List<InfluxDbSourceSplit> snapshotState(long id){synchronized(lock){List<InfluxDbSourceSplit> s=new ArrayList<>();if(split!=null)s.add(split);s.addAll(pendingSplits);return s;}}
 public CompletableFuture<Void> isAvailable(){synchronized(lock){if(!records.isEmpty()||exhausted||split==null||System.currentTimeMillis()>=nextPoll)return CompletableFuture.completedFuture(null);CompletableFuture<Void> f=new CompletableFuture<>();CompletableFuture.delayedExecutor(nextPoll-System.currentTimeMillis(),TimeUnit.MILLISECONDS).execute(()->f.complete(null));return f;}}
 public void addSplits(List<InfluxDbSourceSplit> s){synchronized(lock){if(s!=null)for(InfluxDbSourceSplit candidate:s){candidate.state().validateFor("InfluxDB Source",config.cursorType().name(),config.cursorField(),config.idField());pendingSplits.addLast(candidate);}if(split==null&&!pendingSplits.isEmpty())split=pendingSplits.removeFirst();exhausted=false;}}
 public void notifyNoMoreSplits(){noMore=true;} public void close(){exhausted=true;}
 private void load()throws Exception{InfluxDbSourceSplit current=split;List<Map<String,Object>> rows=parse(execute(sql(current.state())));List<Record> batch=new ArrayList<>();for(Map<String,Object> fields:rows){Object cursor=config.cursorField().isBlank()?null:fields.get(config.cursorField());if(!config.cursorField().isBlank()&&cursor==null){LOG.warn("Skipping InfluxDB row with null cursorField {}",config.cursorField());continue;}Object id=config.idField().isBlank()?null:fields.get(config.idField());if(!config.idField().isBlank()&&id==null){LOG.warn("Skipping InfluxDB row with null idField {}",config.idField());continue;}batch.add(new Record(new DataEntity(resolveId(fields),resolveTimestamp(fields),fields,headers(fields)),cursor==null?null:cursorString(cursor),id==null?null:String.valueOf(id)));}if(config.readMode()==ReadMode.INCREMENTAL&&!config.cursorField().isBlank()){batch.sort((left,right)->{int cursorComparison=compareCursor(left.cursor(),right.cursor());return cursorComparison!=0?cursorComparison:compareNullable(left.id(),right.id());});}records.addAll(batch);polls++;if(config.readMode()==ReadMode.FULL)exhausted=true;}
 private int compareCursor(String left,String right){if(left==null)return right==null?0:-1;if(right==null)return 1;return switch(config.cursorType()){case LONG->Long.compare(Long.parseLong(left),Long.parseLong(right));case DOUBLE->Double.compare(Double.parseDouble(left),Double.parseDouble(right));case TIMESTAMP->Instant.parse(left).compareTo(Instant.parse(right));case STRING->left.compareTo(right);};}
 private static int compareNullable(String left,String right){if(left==null)return right==null?0:-1;if(right==null)return 1;return left.compareTo(right);}
 private void emit(ReaderOutput<DataEntity> out){Record r=records.removeFirst();out.collect(r.entity());if(config.readMode()==ReadMode.INCREMENTAL&&r.cursor()!=null)split=new InfluxDbSourceSplit(split.splitId(),new IncrementalSourceState(config.cursorType().name(),config.cursorField(),r.cursor(),config.idField().isBlank()?null:config.idField(),config.idField().isBlank()?null:r.id()),split.pageIndex());}
 private String sql(IncrementalSourceState state){String base=config.sql();if(config.readMode()==ReadMode.FULL&&split!=null&&( !split.measurement().isBlank()||!split.rangeStart().isBlank())){String p=!split.measurement().isBlank()?"\"name\" = '"+split.measurement().replace("'","\\'")+"'":config.splitField()+" >= "+split.rangeStart()+" and "+config.splitField()+(split.endInclusive()?" <= ":" < ")+split.rangeEnd();return append(base,p);}if(config.readMode()==ReadMode.FULL)return base;if(state.cursorValue()==null)return base;String c=literal(coerce(state.cursorValue()),config.cursorType());String p=config.cursorField()+" > "+c;if(!config.idField().isBlank()&&state.uniqueIdValue()!=null)p="("+config.cursorField()+" > "+c+" or ("+config.cursorField()+" = "+c+" and "+config.idField()+" > '"+state.uniqueIdValue().replace("'","\\'")+"'))";if(base.contains("${cursor}"))return base.replace("${cursor}",c);return append(base,p);}
 private String execute(String sql)throws Exception{Map<String,String> p=new LinkedHashMap<>();p.put("db",config.database());p.put("q",sql);p.put("epoch",config.epoch());if(!config.username().isBlank())p.put("u",config.username());if(!config.password().isBlank())p.put("p",config.password());HttpRequest req=HttpRequest.newBuilder(URI.create(config.url()+"/query?"+params(p))).timeout(Duration.ofSeconds(config.queryTimeoutSeconds())).GET().build();HttpResponse<String> r=client.send(req,HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("InfluxDB Source query failed with status "+r.statusCode()+": "+r.body());return r.body();}
 private List<Map<String,Object>> parse(String body)throws Exception{JsonNode root=mapper.readTree(body);List<Map<String,Object>> rows=new ArrayList<>();for(JsonNode result:root.path("results")){if(!result.path("error").asText("").isBlank())throw new IllegalStateException(result.path("error").asText());for(JsonNode series:result.path("series")){List<String> cols=new ArrayList<>();series.path("columns").forEach(n->cols.add(n.asText()));Map<String,Object> tags=series.path("tags").isObject()?mapper.convertValue(series.path("tags"),Map.class):Map.of();for(JsonNode value:series.path("values")){Map<String,Object> f=new LinkedHashMap<>();f.put("_measurement",series.path("name").asText(""));f.putAll(tags);for(int i=0;i<cols.size()&&i<value.size();i++)f.put(cols.get(i),mapper.convertValue(value.get(i),Object.class));rows.add(f);}}}return rows;}
 private String resolveId(Map<String,Object> f){Object id=config.idField().isBlank()?null:f.get(config.idField());if(id!=null)return String.valueOf(id);return String.valueOf(f.getOrDefault("_measurement",""))+":"+String.valueOf(f.getOrDefault(timestampField(),""));}
 private long resolveTimestamp(Map<String,Object> f){Object v=f.get(timestampField());if(v instanceof Number n)return epoch(n.longValue());if(v instanceof String s)try{return Instant.parse(s).toEpochMilli();}catch(Exception e){try{return Timestamp.valueOf(s).getTime();}catch(Exception x){}}return System.currentTimeMillis();}
 private String timestampField(){return config.timestampField().isBlank()?"time":config.timestampField();} private Map<String,String> headers(Map<String,Object> f){Map<String,String> h=new HashMap<>();h.put("source","influxdb");h.put("readMode",config.readMode().name());h.put("database",config.database());Object m=f.get("_measurement");if(m!=null)h.put("measurement",String.valueOf(m));if(!config.cursorField().isBlank())h.put("cursorField",config.cursorField());return h;}
 private Object coerce(String v){return switch(config.cursorType()){case LONG->Long.parseLong(v);case DOUBLE->Double.parseDouble(v);case TIMESTAMP->{try{yield Timestamp.from(Instant.parse(v));}catch(Exception e){yield Timestamp.from(Instant.ofEpochMilli(epoch(Long.parseLong(v))));}}case STRING->v;};} private String literal(Object v,CursorType t){return switch(t){case LONG,DOUBLE->String.valueOf(v);case TIMESTAMP,STRING->"'"+String.valueOf(v).replace("'","\\'")+"'";};} private String cursorString(Object v){if(config.cursorType()==CursorType.TIMESTAMP){if(v instanceof Number n)return Instant.ofEpochMilli(epoch(n.longValue())).toString();try{return Instant.parse(String.valueOf(v)).toString();}catch(Exception ignored){}}return v instanceof Timestamp t?t.toInstant().toString():String.valueOf(v);} private long epoch(long v){return switch(config.epoch()){case"n"->v/1_000_000L;case"u"->v/1_000L;case"s"->v*1000L;case"m"->v*60000L;case"h"->v*3600000L;default->v;};}
 private static String append(String sql,String p){String l=sql.toLowerCase(Locale.ROOT);int at=sql.length();for(String t:List.of(" group by "," order by "," limit "," slimit "," tz(")){int i=l.indexOf(t);if(i>=0&&i<at)at=i;}String head=sql.substring(0,at).trim(),tail=sql.substring(at);return head+(l.substring(0,at).contains(" where ")?" and ":" where ")+p+tail;}private static String params(Map<String,String>p){return p.entrySet().stream().map(e->URLEncoder.encode(e.getKey(),StandardCharsets.UTF_8)+"="+URLEncoder.encode(e.getValue(),StandardCharsets.UTF_8)).reduce((a,b)->a+"&"+b).orElse("");}
 private record Record(DataEntity entity,String cursor,String id){}
}
